// GENERATED by new-recipe-renderer.mjs --refresh: one story per recipe in
// ../recipes, so the sidebar reads V12/Recipes/<name>. A hand edit is replaced.
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { RecipeRenderer } from '../components/RecipeRenderer';
import type { Recipe } from '../components/types';
import { recipes } from '../recipes';
import '../components/recipe-renderer.scss';
import mdx from './RecipeRenderer.mdx';

const names = [
  'chat-shell',
  'chat-shell-embedded',
  'create-topic',
  'settings-page',
  'status-tile',
];

const meta: Meta<typeof RecipeRenderer> = {
  title: 'V12/RecipeRenderer',
  tags: ['squad', 'incubating'],
  component: RecipeRenderer,
  parameters: {
    // A recipe is a screen, so it gets the whole canvas: the default padding
    // would inset the shell and read as part of the design.
    layout: 'fullscreen',
    docs: {
      page: mdx,
      // In docs the preview is a box, not the screen, so a recipe that fills
      // the viewport renders its own height inside it and leaves stray ground
      // above and below — measured as a 521px shell in a 601px white preview.
      // An iframe of a stated height makes the two the same thing.
      story: { inline: false, height: '640px' },
    },
  },
  argTypes: {
    recipe: { options: names, mapping: recipes, control: { type: 'select' } },
    onEvent: { action: 'event' },
    className: { control: false },
  },
};

export default meta;
type Story = StoryObj<typeof RecipeRenderer>;

/**
 * Any recipe in recipes/, chosen from the control.
 */
export const Playground: Story = {
  args: { recipe: names[0] as unknown as Recipe },
};

export const ChatShell: Story = {
  name: 'chat-shell',
  args: { recipe: recipes['chat-shell'] },
};

export const ChatShellEmbedded: Story = {
  name: 'chat-shell-embedded',
  args: { recipe: recipes['chat-shell-embedded'] },
};

export const CreateTopic: Story = {
  name: 'create-topic',
  args: { recipe: recipes['create-topic'] },
};

export const SettingsPage: Story = {
  name: 'settings-page',
  args: { recipe: recipes['settings-page'] },
};

export const StatusTile: Story = {
  name: 'status-tile',
  args: { recipe: recipes['status-tile'] },
};
